#[verifier(spec)]
fn is_vowel(c: char) -> bool {
    c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
}

//––––––––––––––––––––––––––––––––––––––––––––––––––––––––––––––––//
