#[verifier(spec)]
fn filter_vowels_seq(s: Seq<char>) -> Seq<char> {
    decreases(s.len());
    if s.len() == 0 {
        Seq::empty()
    } else {
        let c0 = s.index(0);
        let tail = s.subseq(1, s.len());
        let filtered_tail = filter_vowels_seq(tail);
        if is_vowel(c0) {
            // prepend c0 to the filtered_tail
            Seq::unit(c0).concat(filtered_tail)
        } else {
            filtered_tail
        }
    }
}

